sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    // 在此处实现 REST API 的资源逻辑

    // 从 URL 中获取 user_name 路径参数的值（例如：/users/{user_name}）
    // Get value from the user_name path parameter passed in the URL
    var requestUser = request.pathParams.user_name;

    // 从 URL 中获取 ni_query 查询参数的值（例如：?ni_query=...）
    // Get value of the ni_query query parameter passed in the URL
    var requestNIQuery = request.queryParams.ni_query;

    // 查询 sys_user 表，获取与传入的 user_name 匹配的用户记录
    // Query the sys_user table to get the user record for the user passed in
    // the user_id path parameter.  
    var requestUserName = new GlideRecord('sys_user');
    requestUserName.get('user_name', requestUser);
    // 上一行：根据用户名获取用户记录（包含 sys_id 等信息）
	var requestUserName = new GlideRecord('sys_user');
	requestUserName.get('user_name', requestUser);

	// 检查是否找到用户
	if (!requestUserName.user_name) {
	var apiError = new sn_ws_err.ServiceError();
	apiError.setStatus(542);
	apiError.setMessage("User not found");
	apiError.setDetail("No user record found for the user_name passed into the ni_info web service resource using the user_name path parameter.");
	response.setError(apiError);
	return;
	}
    // 获取 NeedIt 表中状态为 active 的记录数量，条件是 u_requested_for 字段等于上一步获取的用户 sys_id
    // encodedQuery 是可选的过滤条件，来自客户端请求的查询参数
    // 按照 u_request_type 字段进行分组统计
    // Get the count of active NeedIt table records where the user from the
    // user_name path parameter is the Requested for.  The encoded query is from the
    // Query Parameter Associations.  Group by category.
    var userNICount = new GlideAggregate('x_58872_needit_needit');
    userNICount.addAggregate('COUNT'); // 添加 COUNT 聚合函数，用于统计每组的数量
    userNICount.addQuery('u_requested_for', requestUserName.sys_id); // 设置查询条件：请求人为当前用户
    userNICount.addEncodedQuery(requestNIQuery); // 添加编码后的查询条件（如状态、时间范围等）
    userNICount.groupBy('u_request_type'); // 按请求类型分组
    userNICount.query(); // 执行聚合查询

    var needitRecs = 0;
    var niUserRecs = []; // 存储每个请求类型的计数结果
    var needitRecsCount = 0; // 总记录数（所有类型的总和）

    // 遍历聚合查询的结果
    while (userNICount.next()) {
        needitRecs = userNICount.getAggregate('COUNT'); // 获取当前分组的记录数
        var reqType = userNICount.u_request_type.getDisplayValue(); // 获取请求类型的显示值（如“硬件”、“软件”等）

        // 将当前请求类型及其数量加入数组
        niUserRecs.push({
            "requestType": reqType,
            "count": needitRecs
        });

        // 累加总数
        needitRecsCount = parseInt(needitRecsCount) + parseInt(needitRecs);
    }

    // 创建一个 body 对象，用于返回给客户端
    //Create a body object.  Add property value pairs to the body.
    var body = {};
    body.totalUserNIRecs = needitRecsCount; // 返回该用户的所有 NeedIt 请求总数
    body.catCounts = niUserRecs; // 返回按类型分类的请求数量
    body.user = {
        "User name": requestUserName.user_name, // 返回用户名
        "User ID": requestUserName.sys_id // 返回用户的唯一系统 ID
    };

    // 设置响应体，将构建好的 body 返回给调用者
    // Send the response object, which is returned to the requestor, to the body object.
    response.setBody(body);

})(request, response);
